declare(strict_types=1);$root=dirname(__DIR__,2);require $root.'/espocrm/bootstrap.php';use Espo\Core\Application;use Espo\Core\InjectableFactory;use Espo\Core\ORM\EntityManager;use Espo\Core\Record\CreateParams;use Espo\Core\Record\ServiceContainer;use Espo\Core\Tenant\TenantContext;use Espo\Core\Tenant\TenantContextStore;use Espo\Custom\Tools\Event\BehaviorEventService;$a=fn($c,$m)=>$c?:throw new RuntimeException($m);$app=new Application();$app->setupSystemUser();$box=$app->getContainer();$em=$box->getByClass(EntityManager::class);$store=$box->getByClass(TenantContextStore::class);$factory=$box->getByClass(InjectableFactory::class);$records=$box->getByClass(ServiceContainer::class);$tx=$em->getTransactionManager();$ta=new TenantContext('30000000-0000-4000-8000-000000000001','isolation-alpha','event-test');$tb=new TenantContext('30000000-0000-4000-8000-000000000002','isolation-beta','event-test');$tx->start();try{$contact=$store->runWith($ta,fn()=>$records->get('Contact')->create((object)['firstName'=>'Event','lastName'=>'Contact'],CreateParams::create()));$input=(object)['eventType'=>'page.viewed','source'=>'contract-test','idempotencyKey'=>'same-retry-key','visitorKey'=>'raw-browser-key','contactId'=>$contact->getId(),'pageUrl'=>'https://example.test/pricing','properties'=>(object)['title'=>'Pricing'],'consent'=>(object)['analytics'=>'granted']];$one=$store->runWith($ta,fn()=>$factory->create(BehaviorEventService::class)->ingest($input));$two=$store->runWith($ta,fn()=>$factory->create(BehaviorEventService::class)->ingest($input));$a(!$one['duplicate']&&$two['duplicate']&&$one['id']===$two['id'],'Retry was not idempotent.');$other=$store->runWith($tb,fn()=>$factory->create(BehaviorEventService::class)->ingest((object)['eventType'=>'page.viewed','source'=>'contract-test','idempotencyKey'=>'same-retry-key','visitorKey'=>'raw-browser-key']));$a($other['id']!==$one['id'],'Idempotency leaked across tenants.');$pdo=$em->getPDO();$q=$pdo->prepare('SELECT COUNT(*) FROM nexa_timeline_event WHERE tenant_id=? AND source_entity_id=?');$q->execute([$ta->tenantId,$one['id']]);$a((int)$q->fetchColumn()===1,'Known event missing timeline projection.');$q=$pdo->prepare('SELECT COUNT(*) FROM nexa_outbox_event WHERE tenant_id=? AND aggregate_id=?');$q->execute([$ta->tenantId,$one['id']]);$a((int)$q->fetchColumn()===1,'Event missing outbox record.');echo "Tenant behavior event tests passed.\n";}finally{$tx->rollback();}
